{
  "name": "通用USB设备",
  "name_en": "Generic USB Device",
  "manufacturer": "",
  "description": "通过USB连接到计算机的通用设备或实验仪器。此类设备可被主机枚举、配置，并通过控制端点及数据端点进行读写通信，适用于实验室中对各类USB接口仪器进行识别、配置和基础数据交换。",
  "description_en": "A general USB-connected device or laboratory instrument. Such a device can be enumerated and configured by a host computer and communicated with through control and data endpoints, making it suitable for identifying, configuring, and exchanging basic data with USB instruments in the lab.",
  "tag_hints": [
    "USB communication",
    "device enumeration",
    "control transfer",
    "endpoint read/write",
    "instrument integration"
  ],
  "actions": [
    {
      "action_name": "auto-configurations",
      "description": "列出设备支持的USB配置。",
      "description_en": "List the USB configurations supported by the device."
    },
    {
      "action_name": "auto-langids",
      "description": "读取设备支持的USB语言ID。",
      "description_en": "Read the USB language IDs supported by the device."
    },
    {
      "action_name": "auto-serial_number",
      "description": "读取设备序列号字符串。",
      "description_en": "Read the device serial number string."
    },
    {
      "action_name": "auto-product",
      "description": "读取设备产品名称字符串。",
      "description_en": "Read the device product name string."
    },
    {
      "action_name": "auto-parent",
      "description": "获取设备在USB拓扑中的上级设备。",
      "description_en": "Get the parent device in the USB topology."
    },
    {
      "action_name": "auto-manufacturer",
      "description": "读取设备制造商字符串。",
      "description_en": "Read the device manufacturer string."
    },
    {
      "action_name": "auto-backend",
      "description": "获取当前使用的USB通信后端信息。",
      "description_en": "Get information about the USB communication backend currently in use."
    },
    {
      "action_name": "auto-set_configuration",
      "description": "设置设备的活动USB配置。",
      "description_en": "Set the active USB configuration of the device."
    },
    {
      "action_name": "auto-get_active_configuration",
      "description": "读取设备当前活动的USB配置。",
      "description_en": "Read the device's current active USB configuration."
    },
    {
      "action_name": "auto-set_interface_altsetting",
      "description": "设置设备接口的备用设置。",
      "description_en": "Set an alternate setting for a device interface."
    },
    {
      "action_name": "auto-clear_halt",
      "description": "清除指定端点的停止或STALL状态。",
      "description_en": "Clear the halt or STALL condition on a specified endpoint."
    },
    {
      "action_name": "auto-reset",
      "description": "复位设备。",
      "description_en": "Reset the device."
    },
    {
      "action_name": "auto-write",
      "description": "向设备指定端点写入数据。",
      "description_en": "Write data to a specified device endpoint."
    },
    {
      "action_name": "auto-read",
      "description": "从设备指定端点读取数据。",
      "description_en": "Read data from a specified device endpoint."
    },
    {
      "action_name": "auto-ctrl_transfer",
      "description": "通过控制端点执行USB控制传输。",
      "description_en": "Perform a USB control transfer through the control endpoint."
    },
    {
      "action_name": "auto-is_kernel_driver_active",
      "description": "检查指定接口是否已绑定内核驱动。",
      "description_en": "Check whether a kernel driver is active on the specified interface."
    },
    {
      "action_name": "auto-detach_kernel_driver",
      "description": "将指定接口与内核驱动分离。",
      "description_en": "Detach the kernel driver from the specified interface."
    },
    {
      "action_name": "auto-attach_kernel_driver",
      "description": "为指定接口重新附加内核驱动。",
      "description_en": "Re-attach the kernel driver to the specified interface."
    }
  ]
}

